CREATE TYPE "Role" AS ENUM ('EMPLOYEE', 'MANAGER');
CREATE TYPE "PostingStatus" AS ENUM ('OPEN', 'PENDING_APPROVAL', 'COMPLETED');
CREATE TYPE "ClaimStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Shift" ("id" TEXT NOT NULL, "assignedUserId" TEXT NOT NULL, "startAt" TIMESTAMP(3) NOT NULL, "endAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Shift_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Availability" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "startAt" TIMESTAMP(3) NOT NULL, "endAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Availability_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ShiftPosting" ("id" TEXT NOT NULL, "shiftId" TEXT NOT NULL, "postedById" TEXT NOT NULL, "status" "PostingStatus" NOT NULL DEFAULT 'OPEN', CONSTRAINT "ShiftPosting_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ShiftPosting_shiftId_key" ON "ShiftPosting"("shiftId");
CREATE TABLE "ShiftClaim" ("id" TEXT NOT NULL, "postingId" TEXT NOT NULL, "claimantId" TEXT NOT NULL, "status" "ClaimStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ShiftClaim_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notification" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "message" TEXT NOT NULL, "read" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL, "actorId" TEXT NOT NULL, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Shift" ADD CONSTRAINT "Shift_assignedUserId_fkey" FOREIGN KEY ("assignedUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Availability" ADD CONSTRAINT "Availability_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ShiftPosting" ADD CONSTRAINT "ShiftPosting_shiftId_fkey" FOREIGN KEY ("shiftId") REFERENCES "Shift"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ShiftPosting" ADD CONSTRAINT "ShiftPosting_postedById_fkey" FOREIGN KEY ("postedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ShiftClaim" ADD CONSTRAINT "ShiftClaim_postingId_fkey" FOREIGN KEY ("postingId") REFERENCES "ShiftPosting"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ShiftClaim" ADD CONSTRAINT "ShiftClaim_claimantId_fkey" FOREIGN KEY ("claimantId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AuditEvent" ADD CONSTRAINT "AuditEvent_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
